# Let me try a different reachability analysis
# Fill cells based on which edges can access their component

def flood_from_all_edges(grid, rows, cols):
    from collections import deque

    # Store which edges reach each 0-cell
    edge_reaches = {}

    for edge_name in ['top', 'bottom', 'left', 'right']:
        q = deque()
        visited = set()

        if edge_name == 'top':
            for c in range(cols):
                if grid[0][c] == 0:
                    q.append((0, c))
                    visited.add((0, c))

        elif edge_name == 'bottom':
            for c in range(cols):
                if grid[rows-1][c] == 0:
                    q.append((rows-1, c))
                    visited.add((rows-1, c))

        elif edge_name == 'left':
            for r in range(rows):
                if grid[r][0] == 0:
                    q.append((r, 0))
                    visited.add((r, 0))

        elif edge_name == 'right':
            for r in range(rows):
                if grid[r][cols-1] == 0:
                    q.append((r, cols-1))
                    visited.add((r, cols-1))

        while q:
            r, c = q.popleft()
            if (r, c) not in edge_reaches:
                edge_reaches[(r, c)] = set()
            edge_reaches[(r, c)].add(edge_name)

            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == 0 and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        q.append((nr, nc))

    return edge_reaches

